do $$ begin if not exists(select 1 from pg_policies where schemaname='public' and tablename='order_item_options' and policyname='order_item_options_own_insert') then create policy order_item_options_own_insert on public.order_item_options for insert to authenticated with check (exists(select 1 from public.order_items i where i.id=order_item_id and i.customer_id=(select auth.uid()))); end if; end $$;